// Geminiが返したテキスト（JSON文字列）を取り出す。ノード構成で入る場所が違うため複数候補を見る。
let raw = $json.text ?? $json.content ?? $json.response ?? $json.output ?? $json.data ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
// ```json ... ``` のコードフェンスが付く場合があるので除去
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let p = {};
try {
  p = JSON.parse(raw);
} catch (e) {
  p = { transaction_date: '', vendor: '', amount: 0, doc_type: '', _parse_error: String(e), _raw: raw };
}
const num = (v) => { const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
return [{ json: {
  "取引日": p.transaction_date || '',
  "取引先": p.vendor || '',
  "金額": num(p.amount),
  "書類種別": p.doc_type || ''
} }];
